"""Auto-generated validation report (revision plan 8.1 step 3, 8.2 "hand-written regulatory docs").

The ML part of the technical documentation is generated from the run itself, so it can never
disagree with the artefacts it describes.
"""

from __future__ import annotations

from typing import Any

import pandas as pd

from xrayml.artifacts import OperatingPointSet


def _fmt(v: Any) -> str:
    if v is None:
        return "—"
    if isinstance(v, float):
        return str(int(v)) if v.is_integer() and abs(v) >= 1 else f"{v:.3f}"
    if isinstance(v, tuple | list) and len(v) == 2 and all(isinstance(x, float) for x in v):
        return f"[{v[0]:.3f}, {v[1]:.3f}]"
    return str(v)


def _table(rows: list[dict]) -> list[str]:
    if not rows:
        return ["_none_"]
    cols = list(rows[0])
    out = ["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    out += ["| " + " | ".join(_fmt(r[c]) for c in cols) + " |" for r in rows]
    return out


def validation_report(
    model_card: dict[str, Any],
    test_metrics: dict[str, Any],
    ops: OperatingPointSet,
    confirm: pd.DataFrame,
    gate: dict[str, Any] | None = None,
    external_metrics: dict[str, Any] | None = None,
) -> str:
    lines = [
        f"# Validation report — model {model_card.get('model_version', '?')}",
        "",
        "## Lineage",
        "",
        f"- task: `{model_card.get('task')}` · architecture: `{model_card.get('architecture')}` · input: {model_card.get('image_size')} px",
        f"- git SHA: `{model_card.get('git_sha')}`",
        f"- dataset: `{model_card.get('dataset_version')}` (fingerprint `{model_card.get('dataset_fingerprint')}`)",
        f"- operating points: `{ops.version}` tuned on split `{ops.tuning_split}`",
        "",
        "## Standalone performance (test split)",
        "",
    ]
    keys = [
        k for k in ["n", "prevalence", "auc", "auc_ci", "ap", "ece", "cpm", "dice_pos"] if k in test_metrics
    ]
    lines += _table([{k: test_metrics[k] for k in keys}])
    if external_metrics:
        lines += ["", "## External test (unseen site)", ""]
        lines += _table([{k: external_metrics.get(k) for k in keys}])
    lines += ["", "## Operating points (tuned on val, confirmed on test)", ""]
    lines += _table(confirm.to_dict("records") if not confirm.empty else [])
    lines += ["", "## Subgroups (test)", ""]
    for col, rows in test_metrics.get("subgroups", {}).items():
        lines += [f"### by {col}", "", *_table(rows), ""]
    if gate is not None:
        lines += ["## Release gate", "", f"**{'PASSED' if gate['passed'] else 'FAILED'}**", ""]
        lines += _table(gate["checks"])
    lines += ["", "_Generated by `xrayml report`. Do not edit by hand: regenerate from the run._", ""]
    return "\n".join(lines)
